283	function canonicalArchiveRoot(string $path, string $cwd): string
284	{
285	    $archiveRoot = normalizedAbsolutePath(rtrim($path, '/'), $cwd);
286	
287	    if (is_link($archiveRoot)) {
288	        throw new RuntimeException("Archive root must not be a symlink: {$archiveRoot}");
