305	function normalizedAbsolutePath(string $path, string $cwd): string
306	{
307	    $absolutePath = str_starts_with($path, '/') ? $path : rtrim($cwd, '/').'/'.$path;
308	    $parts = [];
309	
310	    foreach (explode('/', $absolutePath) as $part) {
